 private static final VoxelShape[][] SHAPES=new VoxelShape[4][CELLS.length];
 static{for(Direction f:Direction.Plane.HORIZONTAL)for(int i=0;i<CELLS.length;i++){
  VoxelShape s=Shapes.empty();int[] cell=CELLS[i];
  for(double[] b:BOXES){double x0=Math.max(0,b[0]+.5-cell[0]),y0=Math.max(0,b[1]-cell[1]),z0=Math.max(0,b[2]+.5-cell[2]);
   double x1=Math.min(1,b[3]+.5-cell[0]),y1=Math.min(1,b[4]-cell[1]),z1=Math.min(1,b[5]+.5-cell[2]);
   if(x1<=x0 || y1<=y0 || z1<=z0)continue;
   double[] p=rotate(x0-.5,z0-.5,f),q=rotate(x1-.5,z1-.5,f);
   s=Shapes.or(s,Shapes.box(Math.min(p[0],q[0])+.5,y0,Math.min(p[1],q[1])+.5,Math.max(p[0],q[0])+.5,y1,Math.max(p[1],q[1])+.5));
  }SHAPES[f.get2DDataValue()][i]=s.optimize();
 }}
 private static double[] rotate(double x,double z,Direction f){return switch(f){case SOUTH->new double[]{-x,-z};case EAST->new double[]{-z,x};case WEST->new double[]{z,-x};default->new double[]{x,z};};}
 public static BlockPos cell(BlockPos root,Direction f,int i){int[] c=CELLS[i];double[] p=rotate(c[0],c[2],f);return root.offset((int)p[0],c[1],(int)p[1]);}
 public static BlockPos root(BlockPos p,Direction f,int i){BlockPos offset=cell(BlockPos.ZERO,f,i);return p.offset(-offset.getX(),-offset.getY(),-offset.getZ());}
 public static VoxelShape shape(Direction f,int i){return SHAPES[f.get2DDataValue()][i];}
